CREATE TABLE public.user_badges (user_id uuid NOT NULL, badge_id text NOT NULL, earned_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,badge_id));
GRANT SELECT ON public.user_badges TO authenticated;
GRANT ALL ON public.user_badges TO service_role;
ALTER TABLE public.user_badges ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own earned badges" ON public.user_badges FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE TABLE public.user_featured_badges (user_id uuid NOT NULL, badge_id text NOT NULL, position smallint NOT NULL CHECK(position BETWEEN 1 AND 3), PRIMARY KEY(user_id,position), UNIQUE(user_id,badge_id), FOREIGN KEY(user_id,badge_id) REFERENCES public.user_badges(user_id,badge_id));
GRANT SELECT ON public.user_featured_badges TO authenticated;
GRANT ALL ON public.user_featured_badges TO service_role;
ALTER TABLE public.user_featured_badges ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own featured badges" ON public.user_featured_badges FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE FUNCTION public.badge_rules() RETURNS TABLE(badge_id text, metric text, threshold integer) LANGUAGE sql IMMUTABLE SET search_path=public AS $$ VALUES ('prima-impronta','cities',1),('esploratore-curioso','cities',5),('viandante','cities',10),('passaporto-vissuto','cities',25),('girovago','cities',50),('cento-orizzonti','cities',100),('tre-terre','regions',3),('cinque-regioni','regions',5),('attraverso-italia','regions',10),('italia-in-tasca','regions',20),('primo-ricordo','memories',1),('album-di-viaggio','memories',5) $$;
REVOKE ALL ON FUNCTION public.badge_rules() FROM PUBLIC;
COMMENT ON FUNCTION public.badge_rules() IS 'Thresholds mirror src/lib/badges.ts; change together and test parity. No client-controlled awards.';
CREATE FUNCTION public.badge_metrics(_user uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('cities',count(DISTINCT v.istat_code),'regions',count(DISTINCT m.region_code),'memories',count(DISTINCT v.istat_code) FILTER (WHERE EXISTS (SELECT 1 FROM public.visit_media vm WHERE vm.user_id=_user AND vm.istat_code=v.istat_code AND vm.media_type IN ('photo','video') AND EXISTS (SELECT 1 FROM storage.objects so WHERE so.bucket_id='visit-media' AND so.name=vm.storage_path AND split_part(so.name,'/',1)=_user::text)))) FROM public.user_visits v JOIN public.municipalities m ON m.istat_code=v.istat_code WHERE v.user_id=_user AND v.visited $$;
REVOKE ALL ON FUNCTION public.badge_metrics(uuid) FROM PUBLIC;
CREATE FUNCTION public.award_user_badges(_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE metrics jsonb; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(_user::text,0)); metrics:=public.badge_metrics(_user); INSERT INTO public.user_badges(user_id,badge_id) SELECT _user,r.badge_id FROM public.badge_rules() r WHERE (metrics->>r.metric)::integer>=r.threshold ON CONFLICT(user_id,badge_id) DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.award_user_badges(uuid) FROM PUBLIC;
CREATE FUNCTION public.sync_my_badges() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; PERFORM public.award_user_badges(uid); RETURN jsonb_build_object('earned',coalesce((SELECT jsonb_agg(jsonb_build_object('badge_id',badge_id,'earned_at',earned_at) ORDER BY earned_at,badge_id) FROM public.user_badges WHERE user_id=uid),'[]'::jsonb),'featured',coalesce((SELECT jsonb_agg(jsonb_build_object('badge_id',badge_id,'position',position) ORDER BY position) FROM public.user_featured_badges WHERE user_id=uid),'[]'::jsonb),'metrics',public.badge_metrics(uid)); END $$;
REVOKE ALL ON FUNCTION public.sync_my_badges() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.sync_my_badges() TO authenticated;
CREATE FUNCTION public.set_my_featured_badges(_ids text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(uid::text,0)); IF _ids IS NULL OR cardinality(_ids)>3 OR EXISTS(SELECT 1 FROM unnest(_ids) id WHERE id IS NULL) OR (SELECT count(DISTINCT id) FROM unnest(_ids) id)<>cardinality(_ids) THEN RAISE EXCEPTION 'Choose at most three unique badges'; END IF; IF EXISTS(SELECT 1 FROM unnest(_ids) id WHERE NOT EXISTS(SELECT 1 FROM public.user_badges b WHERE b.user_id=uid AND b.badge_id=id)) THEN RAISE EXCEPTION 'Badge not earned'; END IF; DELETE FROM public.user_featured_badges WHERE user_id=uid; INSERT INTO public.user_featured_badges(user_id,badge_id,position) SELECT uid,id,ordinality::smallint FROM unnest(_ids) WITH ORDINALITY AS t(id,ordinality); END $$;
REVOKE ALL ON FUNCTION public.set_my_featured_badges(text[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_my_featured_badges(text[]) TO authenticated;
CREATE FUNCTION public.badges_after_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.award_user_badges(NEW.user_id); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.badges_after_change() FROM PUBLIC;
CREATE TRIGGER award_badges_on_visit AFTER INSERT OR UPDATE ON public.user_visits FOR EACH ROW EXECUTE FUNCTION public.badges_after_change();
CREATE TRIGGER award_badges_on_media AFTER INSERT OR UPDATE ON public.visit_media FOR EACH ROW EXECUTE FUNCTION public.badges_after_change();